rss.channel:
    Crow Intelligence
    {{ SITEURL }}/
    Essays and interactive research from Crow Intelligence, an independent lab studying how language shapes thought.
    en

{% for item in (APORIA + PROJECTS) | sort(attribute='date', reverse=true) %}
{% set url = item.url.split('#')[0] %}
{% if url not in ns.seen %}
{% set ns.seen = ns.seen + [url] %}
    {# Jinja autoescaping is off in Pelican, so escape explicitly: titles and
       descriptions contain ampersands (e.g. "Clark & Chalmers"). #}


      {{ item.title | e }}
      {{ SITEURL }}{{ url | e }}
      {{ SITEURL }}{{ url | e }}
      {{ item.date | rfc822 }}
      {{ item.description | e }}

{% endif %}
{% endfor %}
